// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Filter".

Apply three color filters to a 2D shader, with each filter being randomized every so often.
*/

let theShader, dpr = Math.max(1, window.devicePixelRatio), ww = window.innerWidth*dpr, wh = window.innerHeight*dpr;
const canvasStyle = 'width:100%;height:auto;touch-action:none;object-fit:contain;'

function windowResized() {
	ww = window.innerWidth*dpr; wh = window.innerHeight*dpr;
  resizeCanvas(wh*4/3, wh);
	const canvas = document.querySelector('canvas');
	canvas.style = canvasStyle;
}

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2658698/files/vert.glsl', 'frag.glsl');
}

function setup() {
  pixelDensity(1);
  createCanvas(wh*4/3, wh, WEBGL);
	var canvas = document.querySelector('canvas');
	canvas.style = canvasStyle;
}

function draw() {
	if (frameCount%200 == 0) save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
  shader(theShader);
  theShader.setUniform("resolution", [width, height]);
  theShader.setUniform("time", millis() / 1000.0);
  rect(0,0,width,height);
}

// Override to enable webgl2 and support for high resolution and retina displays
p5.RendererGL.prototype._initContext = function() {
	try { this.drawingContext = this.canvas.getContext('webgl2', this._pInst._glAttributes) ||
			this.canvas.getContext('experimental-webgl', this._pInst._glAttributes);
		if (this.drawingContext === null) { throw new Error('Error creating webgl context');
		} else { const gl = this.drawingContext; 
			gl.viewport(0, 0, wh*4/3, wh);
			this._viewport = this.drawingContext.getParameter(this.drawingContext.VIEWPORT);
		} } catch (er) { throw er; }
};

function mouseClicked(){
     save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
#define FC gl_FragCoord.xy
#define R resolution
#define TT 60.
#define T mod(time+1.5,TT)
#define MN min(R.x,R.y)
#define S smoothstep
#define N normalize
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
#define hue(a) (.5+.5*cos(6.3*(a+vec3(.9,.416,.577))))
// Returns a pseudo random number for a given point (white noise)
float rnd(vec2 p) {
	p=fract(p*vec2(12.9898,78.233));
	p+=dot(p,p+34.56);
	return fract(p.x*p.y);
}
// Returns a caleidoscopic pattern with a spiral
vec3 pattern(vec2 uv) {
	vec3 col=vec3(0);
	vec2 p=uv, q=uv;
	p=N(p)*log(length(p)*.05);
	p*=rot(log(length(uv))-T*.6);
	vec2 z=vec2(1,atan(p.y,p.x)/6.28318*6.);
	z=mod(z,2.)-1.;
	for (float i=.0; i<3.; i++) {
		q=fract(q*2.)-.5;
		float d=length(q)*exp(-max(length(uv),.0));
		d=sin(d*15.+T)*.2;
		d=abs(d);
		d=sqrt(3e-2/d);
		col+=d;
	}
	col.xz*=rot(z.y+z.x);
	col.xy*=rot(T*.3+cos(z.x)+sin(z.y));
	col=mix(vec3(z.x,cos(z.x-z.y),z.y),vec3((col.r+col.g+col.b)/3.,z), z.y);
	col=sqrt(vec3(col.r*col.r+col.g*col.g+col.b*col.b))/3.;
	col*=hue(5.2+sqrt(col.r*col.r+col.g*col.g+col.b*col.b)/3.);
	return col;
}
// Converts the given color to grayscale
vec3 filter00(vec3 col) {
	return vec3(dot(col,vec3(.21,.71,.07)));
}
// Converts the given color to inverted grayscale
vec3 filter01(vec3 col) {
	return S(.7,.0,filter00(col));
}
// Converts the given color into red
vec3 filter02(vec3 col) {
	return S(-.25,.85,filter00(col)*vec3(1,.1,.1));
}
// Returns the color unmodified
vec3 filter03(vec3 col) {
	return col;
}
void main() {
	vec2 uv=(FC-.5*R)/MN, p=uv;
	uv*=2.3;
	// generate a grid for the filters
	vec2 gv=floor(uv+.5);
	// initialize the color with the pattern
	vec3 col=pattern(p), c=mix(vec3(1),col,.125);
	float t=time*.25, tt=S(.0,1.,S(-.4,.6,fract(t)));
	// generate a new random number every so often depending on the absolute value of the grid's coordinates
	float n=rnd(.1+abs(R.x>R.y?gv.yy:gv.xx)-floor(10.*fract(t*.1)));
	col=(n>=.0 && n<.2)?mix(c,filter00(col),tt):col;
	col=(n>=.2 && n<.4)?mix(c,filter01(col),tt):col;
	col=(n>=.4 && n<.6)?mix(c,filter02(col),tt):col;
	col=(n>=.6 && n<1.)?mix(c,filter03(col),tt):col;
	// vignette
	uv=FC/R*2.-1.;
	uv*=.7;
	float v=pow(dot(uv,uv),1.8);
	col=mix(col,vec3(0),v);
	// fade scene in and out after a given time and restart the animation
	col=max(mix(col,vec3(0),S(1.-.3/TT,1.,sin(T/TT*6.283185307+1.6)*.5+.5)),.0);
	// fade in the scene at the very beginning
	col=max(col,mix(.0,.08,min(time*.1,1.)));
	O=vec4(col,1);
}

